import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;

public final class HuffmanCoding {

    private HuffmanCoding() {
        // Utility class.
    }

    private static final String SINGLE_SYMBOL_CODE = "0";

    private static final class Node {
        final int weight;
        final int sequence; // Tie-break by original position to keep output deterministic.
        final Node left;
        final Node right;

        private Node(int weight, int sequence, Node left, Node right) {
            this.weight = weight;
            this.sequence = sequence;
            this.left = left;
            this.right = right;
        }

        static Node leaf(int weight, int sequence) {
            return new Node(weight, sequence, null, null);
        }

        static Node branch(Node left, Node right) {
            Objects.requireNonNull(left, "left must not be null");
            Objects.requireNonNull(right, "right must not be null");
            return new Node(left.weight + right.weight, Math.min(left.sequence, right.sequence), left, right);
        }

        boolean isLeaf() {
            return left == null && right == null;
        }
    }

    private static final Comparator<Node> NODE_COMPARATOR = Comparator
            .comparingInt((Node node) -> node.weight)
            .thenComparingInt(node -> node.sequence);

    /**
     * Builds Huffman codes for the provided frequencies.
     *
     * <p>The returned list follows the tree traversal order used by the original
     * implementation, which matches the expected ordering for the existing API.
     * The {@code symbols} argument is validated only for length compatibility.
     */
    public static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
        Objects.requireNonNull(symbols, "symbols must not be null");
        Objects.requireNonNull(frequencies, "frequencies must not be null");

        if (symbols.length() != frequencies.length) {
            throw new IllegalArgumentException("symbols and frequencies must have the same length");
        }

        return buildHuffmanCodes(frequencies);
    }

    private static ArrayList<String> buildHuffmanCodes(int[] frequencies) {
        if (frequencies.length == 0) {
            return new ArrayList<>();
        }

        validateFrequencies(frequencies);
        return HuffmanTree.fromFrequencies(frequencies).codesInTraversalOrder();
    }

    private static void validateFrequencies(int[] frequencies) {
        for (int frequency : frequencies) {
            if (frequency < 0) {
                throw new IllegalArgumentException("frequencies must be non-negative");
            }
        }
    }

    private static final class HuffmanTree {
        private final Node root;

        private HuffmanTree(Node root) {
            this.root = root;
        }

        static HuffmanTree fromFrequencies(int[] frequencies) {
            return new HuffmanTree(mergeNodes(createQueue(frequencies)));
        }

        private static PriorityQueue<Node> createQueue(int[] frequencies) {
            PriorityQueue<Node> queue = new PriorityQueue<>(NODE_COMPARATOR);
            for (int i = 0; i < frequencies.length; i++) {
                queue.add(Node.leaf(frequencies[i], i));
            }
            return queue;
        }

        private static Node mergeNodes(PriorityQueue<Node> queue) {
            while (queue.size() > 1) {
                Node left = queue.poll();
                Node right = queue.poll();
                queue.add(Node.branch(left, right));
            }
            return queue.peek();
        }

        ArrayList<String> codesInTraversalOrder() {
            ArrayList<String> codes = new ArrayList<>();
            collectCodes(root, new StringBuilder(), codes);
            return codes;
        }

        private void collectCodes(Node node, StringBuilder path, List<String> codes) {
            if (node == null) {
                return;
            }

            if (node.isLeaf()) {
                codes.add(path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString());
                return;
            }

            traverseChild(node.left, '0', path, codes);
            traverseChild(node.right, '1', path, codes);
        }

        private void traverseChild(Node child, char bit, StringBuilder path, List<String> codes) {
            path.append(bit);
            collectCodes(child, path, codes);
            path.setLength(path.length() - 1);
        }
    }
}
